def max_edges(n, altitudes):
    altitudes.sort()
    max_edges = 0
    for i in range(n):
        for j in range(i):
            if altitudes[i] > altitudes[j]:
                max_edges += 1
    return max_edges

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        altitudes = list(map(int, input().split()))
        results.append(max_edges(n, altitudes))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
